/**
 * What @memaxlabs/compiler writes into the home files for the demo's
 * Personal Brief B-0001 (demo-brief-data.ts: M-0027 under Conventions,
 * M-0012 and M-0019 under Preferences): generated by running the real
 * compiler's home adapters on the demo record, then pasted here. Claude
 * Code's rules file and the canonical copy are Memax's whole; Codex gets
 * one managed block in the person's own `~/.codex/AGENTS.md`, and the
 * server only ever holds the block. The demo rewrites the header's run
 * and time per target (targets-demo.ts). Regenerate it when the demo
 * record changes. Data, not copy.
 */
import type { DemoCompiled } from "./demo-compiled";

const REFS = ["M-0012", "M-0019", "M-0027"];

const HEADER =
  "<!-- Compiled by Memax from personal at 2026-10-05 16:42 UTC (C-0875). Edit it at https://memax.app/personal/brief; edits here come back as proposals. -->\n";

const BODY = `# Personal

The person you work with keeps these in Memax. Where a project's own files disagree, follow the project.

## Conventions
- Use the gh CLI for GitHub, never raw API calls. [M-0027]

## Preferences
- Reply in English unless the thread is in Chinese. [M-0012]
- Explain a diff before proposing a rewrite. [M-0019]
`;

const HOME_TAIL =
  "\nThe rest of what they keep is live over the memax MCP server: memax_recall, memax_search, memax_get.\n";

/** `~/.claude/rules/memax-personal.md`: Memax's own file, no frontmatter, so it loads in every session. */
export const DEMO_HOME_CLAUDE: DemoCompiled = {
  content: HEADER + BODY + HOME_TAIL,
  bytes: 580,
  lines: 13,
  refs: REFS,
  cites: REFS,
  dropped: [],
};

/** Memax's block in the person's `~/.codex/AGENTS.md`: their own lines stay on the machine. */
export const DEMO_HOME_CODEX: DemoCompiled = {
  content: `<!-- memax:start -->\n${HEADER}${BODY}${HOME_TAIL}<!-- memax:end -->\n`,
  bytes: 620,
  lines: 15,
  refs: REFS,
  cites: REFS,
  dropped: [],
};

/** `~/.memax/personal/AGENTS.md`: the canonical copy, for people and agents with no file of their own. */
export const DEMO_HOME_CANONICAL: DemoCompiled = {
  content: `${HEADER}${BODY}\n## Live context\nUse the memax MCP server for anything not here:\nmemax_recall, memax_search, memax_get. Propose with memax_push.\n`,
  bytes: 607,
  lines: 15,
  refs: REFS,
  cites: REFS,
  dropped: [],
};

/** The block as Memax last wrote it on ziyang-mbp (C-0876), before the hand edit. */
export const DEMO_CODEX_DELIVERED = DEMO_HOME_CODEX.content.replace(
  "(C-0875)",
  "(C-0876)",
);

/** The block on ziyang-mbp now: M-0027 reworded, and a line of the person's own added under it. */
export const DEMO_CODEX_OBSERVED = DEMO_CODEX_DELIVERED.replace(
  "- Use the gh CLI for GitHub, never raw API calls. [M-0027]\n",
  "- Use the gh CLI for GitHub; raw API calls only in scripts. [M-0027]\n- Keep commit subjects under 72 characters.\n",
);

/** What parse-back reads in that edit, line numbers within the block. */
export const DEMO_CODEX_CHANGES = [
  {
    kind: "edit" as const,
    ref: "M-0027",
    old_text: "Use the gh CLI for GitHub, never raw API calls.",
    new_text: "Use the gh CLI for GitHub; raw API calls only in scripts.",
    old_line: 8,
    new_line: 8,
  },
  {
    kind: "new" as const,
    text: "Keep commit subjects under 72 characters.",
    line: 9,
    section: "Conventions",
  },
];
